import React from 'react';
import TestRenderer, { act } from 'react-test-renderer';
import BloodTypeChooser from '../src/components/blood-type-chooser-component/blood-type-chooser-component';

const translations: Record<string, string> = {
  'health_info.blood_type_not_sure': '不确定',
};

jest.mock('react-native-raw-bottom-sheet', () => {
  const ReactModule = require('react');
  const { View } = require('react-native');

  return ReactModule.forwardRef(
    (
      { children }: { children?: React.ReactNode },
      _ref: React.Ref<unknown>,
    ) => ReactModule.createElement(View, null, children),
  );
});

jest.mock('react-native-extended-stylesheet', () => ({
  __esModule: true,
  default: {
    create: <T,>(styleSheet: T): T => styleSheet,
  },
}));

jest.mock('@fortawesome/react-native-fontawesome', () => ({
  FontAwesomeIcon: 'MockFontAwesomeIcon',
}));

jest.mock('@fortawesome/free-solid-svg-icons', () => ({
  faChevronDown: {},
  faGlobeAsia: {},
}));

jest.mock('@constants', () => ({
  __esModule: true,
  default: {
    i18n: {
      t: (key: string): string => translations[key] ?? key,
    },
  },
}));

const globalWithI18n = global as typeof globalThis & {
  $i18n: { t: (key: string) => string };
};

globalWithI18n.$i18n = {
  t: (key: string): string => translations[key] ?? key,
};

const renderedText = (renderer: TestRenderer.ReactTestRenderer): string =>
  JSON.stringify(renderer.toJSON());

describe('BloodTypeChooser', () => {
  test('shows a blood type that arrives after the first render', () => {
    const onSelectBloodType = jest.fn();
    let renderer: TestRenderer.ReactTestRenderer;

    act(() => {
      renderer = TestRenderer.create(
        <BloodTypeChooser
          initValue=""
          onSelectBloodTypeCallback={onSelectBloodType}
        />,
      );
    });

    expect(renderedText(renderer!)).toContain('不确定');
    expect(renderedText(renderer!)).not.toContain('B+');

    act(() => {
      renderer!.update(
        <BloodTypeChooser
          initValue="B+"
          onSelectBloodTypeCallback={onSelectBloodType}
        />,
      );
    });

    expect(renderedText(renderer!)).toContain('B+');
    expect(renderedText(renderer!)).not.toContain('不确定');
  });
});

